    /**
     * Verifies authorize delegates render to the routed form.
     */
    public function testAuthorizeDelegatesToStepRouter(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'step' => StepName::CONSENT->value,
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://example.com');
        $context = new Context($builder, $config);

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->expects($this->once())
            ->method('publicClientData')
            ->with('client-123', 'tenant1', 'https://client.example/callback', 'openid')
            ->willReturn(new ClientData('client-123', ['code'], true));
        $sessions = $this->createMock(SessionManager::class);
        $sessions->expects($this->once())
            ->method('findActiveSession')
            ->willReturn(null);

        $consentForm = $this->createMock(TermsAndGdprConsentForm::class);
        $consentForm->method('render')->willReturn(StepResult::render(new Response(), new ChallengesState()));

        $loginForm = $this->createMock(LoginForm::class);
        $loginForm->method('render')->willReturn(StepResult::render(new Response(), new ChallengesState()));

        $router = new OidcStepRouter(
            $consentForm,
            $this->createMock(ScopeConsentForm::class),
            $loginForm,
            $this->createMock(NewMfaForm::class),
            $this->createMock(NewPassForm::class),
            $this->createMock(UseMfaForm::class),
            $this->createMock(RecoverPassForm::class),
            $this->createMock(DelegateForm::class),
            $this->createMock(RegisterUserForm::class),
            $this->createMock(WebAuthnLoginForm::class),
            $this->createMock(MagicLinkLoginForm::class)
        );

        $cookies = $this->createMock(OidcCookieManager::class);
        $cookies->expects($this->once())
            ->method('clearSession')
            ->willReturnCallback(static fn (ResponseInterface $response): ResponseInterface => $response);

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $sessions,
            $this->createMock(AuthenticateUser::class),
            $this->createMock(HtmlSecurer::class),
            $this->createMock(DecorateHtml::class),
            $this->createMock(OidcResponseBuilder::class),
            $cookies,
            new OidcUrlBuilder($context),
            $router,
            $this->buildRequestResolver($clients),
            $this->messages()
        );

        $response = $authorize->authorize($request, new Response(), ['tenant' => 'tenant1']);

        $this->assertInstanceOf(ResponseInterface::class, $response);
    }

    /**
     * Verifies authorize redirects with invalid_target, before loading any session, when an
     * audience not registered for the client is requested.
     */
    public function testAuthorizeWithForeignAudienceRedirectsWithInvalidTarget(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('GET', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'audience' => 'api-resource,foreign-resource',
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://example.com');
        $context = new Context($builder, $config);

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->method('publicClientData')
            ->willReturn(new ClientData('client-123', ['code'], true, allowedAudiences: ['api-resource']));
        $sessions = $this->createMock(SessionManager::class);
        $sessions->expects($this->never())->method('findActiveSession');
        $cookies = $this->createMock(OidcCookieManager::class);
        $cookies->method('clearSession')
            ->willReturnCallback(static fn (ResponseInterface $response): ResponseInterface => $response);

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $sessions,
            $this->createMock(AuthenticateUser::class),
            $this->createMock(HtmlSecurer::class),
            $this->createMock(DecorateHtml::class),
            $this->createMock(OidcResponseBuilder::class),
            $cookies,
            new OidcUrlBuilder($context),
            new OidcStepRouter(
                $this->createMock(TermsAndGdprConsentForm::class),
                $this->createMock(ScopeConsentForm::class),
                $this->createMock(LoginForm::class),
                $this->createMock(NewMfaForm::class),
                $this->createMock(NewPassForm::class),
                $this->createMock(UseMfaForm::class),
                $this->createMock(RecoverPassForm::class),
                $this->createMock(DelegateForm::class),
                $this->createMock(RegisterUserForm::class),
                $this->createMock(WebAuthnLoginForm::class),
                $this->createMock(MagicLinkLoginForm::class)
            ),
            $this->buildRequestResolver($clients),
            $this->messages()
        );

        $response = $authorize->authorize($request, new Response(), ['tenant' => 'tenant1']);

        $this->assertSame(302, $response->getStatusCode());
        $this->assertSame('https://client.example/callback#error=invalid_target', $response->getHeaderLine('Location'));
    }

    /**
     * Verifies formAuthorize proceeds through the step router.
     */
    public function testFormAuthorizeProceedsWithCsid(): void
    {
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ])
            ->withParsedBody([
                'csid' => 'signed-csid'
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://example.com');
        $context = new Context($builder, $config);

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->expects($this->once())
            ->method('publicClientData')
            ->with('client-123', 'tenant1', 'https://client.example/callback', 'openid')
            ->willReturn(new ClientData('client-123', ['code'], true));

        $securer = $this->createMock(HtmlSecurer::class);
        $securer->expects($this->once())
            ->method('verifyToken')
            ->with('signed-csid')
            ->willReturn('csid-123');

        $authResponse = new PublicLoginAuthResponse(
            tenant: 'tenant1',
            auth: new AuthenticationResult(
                valid: true,
                id: 'user-1',
                name: 'User 1',
                email: 'user@example.com',
                tenant: 'tenant1',
                tenantName: 'Tenant 1',
                scope: 'openid',
                audiences: ['client-123'],
                roles: [],
                groups: []
            ),
            issuer: 'https://example.com/oauth/openid/tenant1',
            clientId: 'client-123',
            sessionId: 'sess-123',
            sessionExpiration: new \DateInterval('PT10M')
        );

        $loginForm = $this->createMock(LoginForm::class);
        $loginForm->expects($this->once())
            ->method('authenticate')
            ->willReturn(StepResult::proceed($authResponse, new ChallengesState()));

        $temporals = $this->createMock(TemporalKeysGateway::class);
        $temporals->expects($this->once())
            ->method('registerTemporalAuthCode')
            ->willReturn('temp-code');

        $consentForm = $this->createMock(TermsAndGdprConsentForm::class);
        $scopesTermsAndGdprConsentForm = $this->createMock(ScopeConsentForm::class);
        $newMfaForm = $this->createMock(NewMfaForm::class);
        $newPassForm = $this->createMock(NewPassForm::class);
        $useMfaForm = $this->createMock(UseMfaForm::class);
        $recoverForm = $this->createMock(RecoverPassForm::class);
        $delegateForm = $this->createMock(DelegateForm::class);
        $registerForm = $this->createMock(RegisterUserForm::class);
        $webAuthnForm = $this->createMock(WebAuthnLoginForm::class);
        $magicLinkForm = $this->createMock(MagicLinkLoginForm::class);

        $router = new OidcStepRouter(
            $consentForm,
            $scopesTermsAndGdprConsentForm,
            $loginForm,
            $newMfaForm,
            $newPassForm,
            $useMfaForm,
            $recoverForm,
            $delegateForm,
            $registerForm,
            $webAuthnForm,
            $magicLinkForm
        );

        $cookies = new OidcCookieManager($context, $this->createMock(TokenSigner::class));
        $responseBuilder = new OidcResponseBuilder(
            new TokenFactory($this->createMock(TokenSigner::class), new ClaimsMapper(), $this->createMock(TokenLifetimesGateway::class)),
            $this->createMock(SessionStoreGateway::class),
            $temporals,
            $cookies
        );
        $urlBuilder = new OidcUrlBuilder($context);

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $this->createMock(SessionManager::class),
            $this->createMock(AuthenticateUser::class),
            $securer,
            $this->createMock(DecorateHtml::class),
            $responseBuilder,
            $cookies,
            $urlBuilder,
            $router,
            $this->buildRequestResolver($clients),
            $this->messages()
        );

        $response = $authorize->formAuthorize($request, new Response(), ['tenant' => 'tenant1']);

        $this->assertSame(302, $response->getStatusCode());
        $this->assertStringContainsString('code=temp-code', $response->getHeaderLine('Location'));
        $this->assertStringContainsString('state=state-xyz', $response->getHeaderLine('Location'));
    }

    /**
     * Verifies a request_ref completes a single authorization: a failed issuance can be retried,
     * but replaying the URL once a code was issued (e.g. with the session still active) cannot
     * issue a second one.
     */
    public function testRequestReferenceIssuesOnlyOneCode(): void
    {
        $reference = $this->referenceSigner()->sign(TokenType::AuthorizationRequest, [
            'client_id' => 'client-123',
            'origin' => 'par',
            'params' => [
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid',
                'nonce' => 'nonce-abc',
                'code_challenge' => 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM',
                'code_challenge_method' => 'S256',
            ],
        ], 'tenant1', new \DateInterval('PT30M'));
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams(['client_id' => 'client-123', AuthorizationRequestResolver::REFERENCE_PARAM => $reference])
            ->withParsedBody(['csid' => 'signed-csid']);

        $config = $this->createMock(AppConfig::class);
        $config->method('get')->willReturn('https://example.com');
        $context = new Context(new ContainerBuilder(), $config);
        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->method('publicClientData')->willReturn(new ClientData('client-123', ['code'], true));
        $securer = $this->createMock(HtmlSecurer::class);
        $securer->method('verifyToken')->willReturn('csid-123');
        $loginForm = $this->createMock(LoginForm::class);
        $loginForm->method('authenticate')->willReturn(StepResult::proceed(new PublicLoginAuthResponse(
            tenant: 'tenant1',
            auth: new AuthenticationResult(valid: true, id: 'user-1', tenant: 'tenant1', tenantName: 'Tenant 1', scope: 'openid', audiences: ['client-123']),
            issuer: 'https://example.com/oauth/openid/tenant1',
            clientId: 'client-123',
            sessionId: 'sess-123',
            sessionExpiration: new \DateInterval('PT10M')
        ), new ChallengesState()));
        $temporals = $this->createMock(TemporalKeysGateway::class);
        // The first issuance fails after the reference was closed; the retry must still issue.
        $temporals->expects($this->exactly(2))->method('registerTemporalAuthCode')->willReturnOnConsecutiveCalls(
            $this->throwException(new \RuntimeException('code store down')),
            'temp-code'
        );
        $cookies = new OidcCookieManager($context, $this->createMock(TokenSigner::class));

        $authorize = new AuthorizeHtml(
            $context,
            $clients,
            $this->createMock(SessionManager::class),
            $this->createMock(AuthenticateUser::class),
            $securer,
            $this->createMock(DecorateHtml::class),
            new OidcResponseBuilder(
                new TokenFactory($this->createMock(TokenSigner::class), new ClaimsMapper(), $this->createMock(TokenLifetimesGateway::class)),
                $this->createMock(SessionStoreGateway::class),
                $temporals,
                $cookies
            ),
            $cookies,
            new OidcUrlBuilder($context),
            new OidcStepRouter(
                $this->createMock(TermsAndGdprConsentForm::class),
                $this->createMock(ScopeConsentForm::class),
                $loginForm,
                $this->createMock(NewMfaForm::class),
                $this->createMock(NewPassForm::class),
                $this->createMock(UseMfaForm::class),
                $this->createMock(RecoverPassForm::class),
                $this->createMock(DelegateForm::class),
                $this->createMock(RegisterUserForm::class),
                $this->createMock(WebAuthnLoginForm::class),
                $this->createMock(MagicLinkLoginForm::class)
            ),
            $this->buildRequestResolver($clients),
            $this->messages()
        );

        try {
            $authorize->formAuthorize($request, new Response(), ['tenant' => 'tenant1']);
            $this->fail('The failed issuance must surface');
        } catch (\RuntimeException $ex) {
            $this->assertSame('code store down', $ex->getMessage());
        }

        $first = $authorize->formAuthorize($request, new Response(), ['tenant' => 'tenant1']);
        $this->assertStringContainsString('code=temp-code', $first->getHeaderLine('Location'));

        $replayed = $authorize->formAuthorize($request, new Response(), ['tenant' => 'tenant1']);
        $this->assertSame('https://client.example/callback#error=invalid_request', $replayed->getHeaderLine('Location'));
    }

